// Analytics Page
// Dedicated page for reports, charts, and financial analytics

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Navbar from '../components/Navbar';
import Charts from '../components/Charts';
import SpendingReport from '../components/SpendingReport';
import ReportButtons from '../components/ReportButtons';
import './AnalyticsPage.css';

function AnalyticsPage() {
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchTransactions();
  }, []);

  const fetchTransactions = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:5000/api/transactions', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTransactions(response.data);
    } catch (error) {
      console.log('Error fetching transactions:', error.message);
    } finally {
      setLoading(false);
    }
  };

  // Calculate statistics
  const totalIncome = transactions
    .filter(t => t.type === 'income')
    .reduce((sum, t) => sum + parseFloat(t.amount), 0);

  const totalExpense = transactions
    .filter(t => t.type === 'expense')
    .reduce((sum, t) => sum + parseFloat(t.amount), 0);

  const balance = totalIncome - totalExpense;
  const savingsRate = totalIncome > 0 ? ((balance / totalIncome) * 100).toFixed(2) : 0;

  // Get category breakdown
  const categoryBreakdown = {};
  transactions
    .filter(t => t.type === 'expense')
    .forEach(t => {
      if (!categoryBreakdown[t.category]) {
        categoryBreakdown[t.category] = 0;
      }
      categoryBreakdown[t.category] += parseFloat(t.amount);
    });

  const topCategories = Object.entries(categoryBreakdown)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5);

  return (
    <div className="analytics-page">
      <Navbar />

      {/* Header */}
      <div className="analytics-header">
        <h1>📊 Analytics & Reports</h1>
        <p>View your financial insights and generate reports</p>
      </div>

      {/* Key Metrics */}
      <div className="key-metrics">
        <div className="metric-card">
          <div className="metric-icon">💰</div>
          <div className="metric-content">
            <h3>Total Income</h3>
            <p className="metric-value">₹ {totalIncome.toFixed(2)}</p>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon">💸</div>
          <div className="metric-content">
            <h3>Total Expenses</h3>
            <p className="metric-value">₹ {totalExpense.toFixed(2)}</p>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon">💳</div>
          <div className="metric-content">
            <h3>Net Balance</h3>
            <p className={`metric-value ${balance >= 0 ? 'positive' : 'negative'}`}>
              ₹ {balance.toFixed(2)}
            </p>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon">📈</div>
          <div className="metric-content">
            <h3>Savings Rate</h3>
            <p className="metric-value">{savingsRate}%</p>
          </div>
        </div>
      </div>

      {/* Charts Section */}
      <div className="charts-section">
        <h2>📈 Visual Analytics</h2>
        {loading ? (
          <div className="loading-message">Loading charts...</div>
        ) : transactions.length === 0 ? (
          <div className="empty-message">Add transactions to see charts</div>
        ) : (
          <Charts transactions={transactions} />
        )}
      </div>

      {/* Spending Report Section */}
      <div className="spending-report-section">
        <h2>📋 Spending Report</h2>
        <SpendingReport />
      </div>

      {/* Top Categories */}
      {topCategories.length > 0 && (
        <div className="top-categories-section">
          <h2>🏆 Top Spending Categories</h2>
          <div className="categories-list">
            {topCategories.map((category, index) => (
              <div key={index} className="category-item">
                <div className="category-rank">#{index + 1}</div>
                <div className="category-info">
                  <h4>{category[0]}</h4>
                  <div className="category-bar">
                    <div
                      className="category-progress"
                      style={{
                        width: `${(category[1] / topCategories[0][1]) * 100}%`
                      }}
                    ></div>
                  </div>
                </div>
                <div className="category-amount">₹ {category[1].toFixed(2)}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Report Generation */}
      <div className="report-generation-section">
        <h2>📄 Generate Reports</h2>
        <p className="section-description">
          Download your financial report as PDF or send it to your email
        </p>
        <ReportButtons />
      </div>

      {/* Analytics Tips */}
      <div className="analytics-tips">
        <h2>💡 Analytics Tips</h2>
        <div className="tips-list">
          <div className="tip-item">
            <span className="tip-number">1</span>
            <div className="tip-content">
              <h4>Monitor Your Trends</h4>
              <p>Check your spending trends monthly to identify patterns</p>
            </div>
          </div>

          <div className="tip-item">
            <span className="tip-number">2</span>
            <div className="tip-content">
              <h4>Compare Categories</h4>
              <p>See which categories consume most of your budget</p>
            </div>
          </div>

          <div className="tip-item">
            <span className="tip-number">3</span>
            <div className="tip-content">
              <h4>Track Savings Rate</h4>
              <p>Monitor your savings rate to ensure financial health</p>
            </div>
          </div>

          <div className="tip-item">
            <span className="tip-number">4</span>
            <div className="tip-content">
              <h4>Export Reports</h4>
              <p>Download PDF reports for record keeping and analysis</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default AnalyticsPage;
